// Dibuja una barra de botones y una «página» (dialog con pestañas) con las tasas del flow. Solo en el navegador.
if (typeof document === 'undefined') return 'CLI: sin interfaz (los botones solo existen en el navegador)';
const ID = 'flow-panel-divisas';
document.getElementById(ID)?.remove(); // una sola instancia: cada Run Flow la recrea con datos nuevos
const tasas = [['USD', vars.usd, '$'], ['GBP', vars.gbp, '£'], ['JPY', vars.jpy, '¥'], ['CHF', vars.chf, 'CHF'], ['MXN', vars.mxn, 'MX$']].map(([c, v, s]) => ({ c, v: Number(v), s })).filter(t => Number.isFinite(t.v) && t.v > 0);
if (!tasas.length) return 'Sin tasas: ejecuta el flow';
const fecha = vars.fecha || '';
const host = document.createElement('div'); host.id = ID; document.body.append(host);
const root = host.attachShadow({ mode: 'open' }); // estilos propios: ni pisa los de la app ni la app los pisa
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const n = (v, d = 4) => Number(v).toLocaleString('es-ES', { maximumFractionDigits: d });
root.innerHTML = `<style>
  :host{all:initial;font:13px system-ui,sans-serif;color:#e2e8f0}
  .bar{position:fixed;left:16px;bottom:16px;z-index:50;display:flex;gap:6px;align-items:center;flex-wrap:wrap;max-width:calc(100vw - 32px);background:#0f172a;border:1px solid #334155;border-radius:12px;padding:8px 10px;box-shadow:0 8px 30px #0008}
  .bar b{margin-right:4px;color:#38bdf8} .bar span{color:#94a3b8;margin-left:4px}
  button{font:inherit;color:#e2e8f0;background:#1e293b;border:1px solid #475569;border-radius:8px;padding:6px 10px;cursor:pointer}
  button:hover{background:#334155} button:disabled{opacity:.5;cursor:default} button.x{background:transparent;border-color:transparent;color:#94a3b8}
  dialog{color:#e2e8f0;background:#0b1220;border:1px solid #334155;border-radius:14px;padding:0;width:min(640px,92vw)}
  dialog::backdrop{background:#0009}
  .tabs{display:flex;gap:4px;padding:12px 16px 0} .tabs button.on{background:#38bdf8;color:#0b1220;border-color:#38bdf8}
  .page{padding:16px} .page[hidden]{display:none}
  table{border-collapse:collapse;width:100%} td,th{padding:6px 8px;border-bottom:1px solid #1e293b;text-align:right} th:first-child,td:first-child{text-align:left}
  input{font:inherit;padding:6px 8px;border-radius:8px;border:1px solid #475569;background:#1e293b;color:#e2e8f0;width:120px}
</style>
<div class="bar"><b>💱 EUR · ${esc(fecha)}</b>
  <button id="conv">Conversor</button><button id="tabla">Tabla</button><button id="informe">Informe ↗</button><button id="csv">CSV</button><button id="copiar">Copiar</button><button id="run">▶ Actualizar</button><span id="estado"></span><button id="x" class="x" title="Quitar el panel (el próximo Run Flow lo vuelve a dibujar)">✕</button></div>
<dialog><div class="tabs"><button data-p="conv" class="on">Conversor</button><button data-p="tabla">Tabla</button><button data-p="acerca">Acerca de</button><button id="cerrar" style="margin-left:auto">Cerrar</button></div>
  <div class="page" data-page="conv"><p>Cantidad en EUR: <input id="eur" type="number" value="100" min="0" step="1"></p><table id="convTabla"></table></div>
  <div class="page" data-page="tabla" hidden><table><tr><th>Divisa</th><th>1 EUR =</th><th>1 unidad = EUR</th></tr>${tasas.map(t => `<tr><td>${t.c}</td><td>${n(t.v)}</td><td>${n(1 / t.v)}</td></tr>`).join('')}</table></div>
  <div class="page" data-page="acerca" hidden><p>Este panel lo dibuja un script «después» de la nota «Botones y páginas» cada vez que ejecutas el flow. Vive en un Shadow DOM propio, no guarda nada en el navegador y no relanza el flow solo: cada acción es un clic tuyo. ✕ lo quita.</p><p>Tasas del BCE vía frankfurter.dev · fecha ${esc(fecha)}.</p></div></dialog>`;
const $ = (s) => root.querySelector(s), dlg = $('dialog'), estado = (t) => { $('#estado').textContent = t; };
const pagina = (p) => { root.querySelectorAll('.page').forEach(el => { el.hidden = el.dataset.page !== p; }); root.querySelectorAll('.tabs [data-p]').forEach(b => b.classList.toggle('on', b.dataset.p === p)); if (!dlg.open) dlg.showModal(); };
root.querySelectorAll('.tabs [data-p]').forEach(b => { b.onclick = () => pagina(b.dataset.p); });
const convertir = () => { const eur = Number($('#eur').value) || 0; $('#convTabla').innerHTML = `<tr><th>Divisa</th><th>${n(eur, 2)} EUR =</th></tr>` + tasas.map(t => `<tr><td>${t.c}</td><td>${n(eur * t.v, 2)} ${t.s}</td></tr>`).join(''); };
$('#eur').oninput = convertir; convertir();
$('#conv').onclick = () => pagina('conv'); $('#tabla').onclick = () => pagina('tabla'); $('#cerrar').onclick = () => dlg.close();
const csv = () => 'divisa;eur_a_divisa;divisa_a_eur\n' + tasas.map(t => `${t.c};${t.v};${(1 / t.v).toFixed(6)}`).join('\n');
$('#csv').onclick = () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv()], { type: 'text/csv' })); a.download = `divisas-${fecha || 'hoy'}.csv`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); estado('CSV descargado'); };
$('#copiar').onclick = async () => { try { await navigator.clipboard.writeText(csv()); estado('Tabla copiada'); } catch { estado('Este navegador no deja copiar aquí'); } };
$('#informe').onclick = () => { const w = window.open('', '_blank'); if (!w) { estado('El navegador bloqueó la pestaña nueva'); return; } w.document.write(`<!doctype html><title>Divisas EUR · ${esc(fecha)}</title><body style="font:15px system-ui;padding:32px;max-width:720px;margin:auto"><h1>EUR frente a ${tasas.length} divisas · ${esc(fecha)}</h1><p>Página generada por un script del flow «Scripts 04» de FlowTest a partir de las variables del último Run Flow.</p><table border="1" cellpadding="8" style="border-collapse:collapse"><tr><th>Divisa</th><th>1 EUR =</th></tr>${tasas.map(t => `<tr><td>${t.c}</td><td>${n(t.v)}</td></tr>`).join('')}</table><p><button onclick="print()">Imprimir</button></p></body>`); w.document.close(); };
$('#run').onclick = async () => { $('#run').disabled = true; estado('Ejecutando el flow…'); try { const r = await fetch('/mcp', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' }, body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: 'tools/call', params: { name: 'flow_run', arguments: {} } }) }); if (r.status === 401) throw new Error('el MCP pide token (FLOW_MCP_TOKEN)'); const j = await r.json(); if (j.error) throw new Error(j.error.message); } catch (e) { estado('No se pudo ejecutar: ' + e.message); $('#run').disabled = false; } };
$('#x').onclick = () => host.remove();
return `Panel dibujado a las ${new Date().toLocaleTimeString('es-ES')} con ${tasas.length} divisas`;

